/**
 * FFI-safe error type exposed to all target languages.
 */
public enum PassboltFfiError: Swift.Error {

    
    
    case Transport(reason: String
    )
    case Auth(reason: String
    )
    case Crypto(reason: String
    )
    case Api(status: UInt16, reason: String
    )
    case NotFound(reason: String
    )
    case Config(reason: String
    )
    case InvalidArgument(reason: String
    )
    case Other(reason: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypePassboltFfiError: FfiConverterRustBuffer {
    typealias SwiftType = PassboltFfiError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> PassboltFfiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Transport(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Auth(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Crypto(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Api(
            status: try FfiConverterUInt16.read(from: &buf), 
            reason: try FfiConverterString.read(from: &buf)
            )
        case 5: return .NotFound(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 6: return .Config(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 7: return .InvalidArgument(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 8: return .Other(
            reason: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: PassboltFfiError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Transport(reason):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Auth(reason):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Crypto(reason):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Api(status,reason):
            writeInt(&buf, Int32(4))
            FfiConverterUInt16.write(status, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .NotFound(reason):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Config(reason):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .InvalidArgument(reason):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Other(reason):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(reason, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypePassboltFfiError_lift(_ buf: RustBuffer) throws -> PassboltFfiError {
    return try FfiConverterTypePassboltFfiError.lift(buf)
}

